"from bs4 import BeautifulSoup\n\nwith open('tests/workday/Systems Software Engineer - New College Grad 2026.htm', 'r', encoding='utf-8', errors='ignore') as f:\n    soup = BeautifulSoup(f.read(), 'html.parser')\n\noptions = soup.find_all(lambda tag: tag.get('role') == 'option' or 'option' in tag.get('data-automation-id', '').lower() or 'menu' in tag.get('data-automation-id', '').lower())\nprint(f\"Total option elements in snapshot: {len(options)}\")\nfor opt in options[:10]:\n    print(f\"Option: tag={opt.name}, aid={opt.get('data-automation-id')}, text={opt.text.strip()[:60]}\")\n"